// Bundles BrazilianBonk's engine for the API, which replays reported runs to check them.
//   node scripts/build-horde-engine.mjs
// Run it after changing anything in src/app/features/games/horde/engine and commit the result.
import { build } from 'esbuild';
import { writeFileSync } from 'node:fs';

const HEADER =
  '// Generated by web/scripts/build-horde-engine.mjs from web/src/app/features/games/horde/engine.\n' +
  '// Do not edit: change the engine and run the script again.\n';

export const bundleHordeEngine = async () => {
  const result = await build({
    entryPoints: [new URL('../src/app/features/games/horde/engine/serverBundle.ts', import.meta.url).pathname],
    bundle: true,
    format: 'esm',
    platform: 'node',
    target: 'node20',
    write: false,
    legalComments: 'none',
    charset: 'utf8',
  });
  return HEADER + result.outputFiles[0].text;
};

if (import.meta.url === `file://${process.argv[1]}`) {
  const out = new URL('../../api/src/hordeEngine.gen.js', import.meta.url).pathname;
  writeFileSync(out, await bundleHordeEngine());
  console.log(`wrote ${out}`);
}
